package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.jobs.CollectorNodeFacts;import com.lianxibu.site.domain.identity.NodeTokens;import com.lianxibu.site.repository.jobs.*;import com.lianxibu.site.repository.identity.JdbcNodeStore;import com.lianxibu.site.service.identity.*;
import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import javax.sql.DataSource;import org.h2.jdbcx.JdbcDataSource;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.junit.jupiter.api.*;
class CollectorNodeFactsNativeTest {
 CollectorHeartbeatsNativeTest f;JdbcCollectorNodeFacts facts;NodeIdentityService identity;String owner,token;AtomicReference<Instant> at;Clock clock;
 DataSource source(){var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:node-facts-"+System.nanoTime()+";MODE=MySQL;DB_CLOSE_DELAY=-1");return ds;}
 @BeforeEach void setup()throws Exception{f=new CollectorHeartbeatsNativeTest(){@Override DataSource source(){return CollectorNodeFactsNativeTest.this.source();}};f.setup();f.jdbc.update("DELETE FROM collector_nodes WHERE id=?",f.node);boolean h2=f.db instanceof JdbcDataSource;String json=h2?"CLOB":"JSON",time=h2?"TIMESTAMP(6)":"DATETIME(6)";f.jdbc.execute("CREATE TABLE IF NOT EXISTS users(id VARCHAR(64) PRIMARY KEY)");f.jdbc.execute("CREATE TABLE IF NOT EXISTS request_receipts(principal VARCHAR(80),operation VARCHAR(191),request_key VARCHAR(128),request_hash BINARY(32),status_code INT,response_json "+json+",expires_at "+time+",id VARCHAR(64) PRIMARY KEY,receipt_kind VARCHAR(32),actor_id VARCHAR(64),scope VARCHAR(128),key_hash BINARY(32),original_status VARCHAR(32),current_status VARCHAR(32),result_ref_json "+json+",created_at "+time+",revision BIGINT,UNIQUE(actor_id,scope,key_hash))");f.jdbc.execute("CREATE TABLE IF NOT EXISTS source_runs(id VARCHAR(64) PRIMARY KEY,claim_node_id VARCHAR(64),node_id VARCHAR(64),delivery_state VARCHAR(32),pending_count BIGINT,barrier_closed_at "+time+",result_json "+json+",manifest_hash BINARY(32))");owner=UUID.randomUUID().toString();f.jdbc.update("INSERT INTO users(id) VALUES(?)",owner);at=new AtomicReference<>(f.now);clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return at.get();}};identity=new NodeIdentityService(new JdbcNodeStore(f.db),new NodeTokens(new byte[32]),clock);var created=identity.createNode(new IdentityService.Actor(owner,"owner"),new IdentityService.NodeCreateCommand("Fictional monitored node",List.of(),List.of("heartbeat:write")),"fictional-create-key","fictional-csrf","https://example.invalid");f.node=created.node().id();token=created.token();facts=new JdbcCollectorNodeFacts(f.db,new DataSourceTransactionManager(f.db),clock);}
 @AfterEach void cleanup(){if(f!=null&&f.node!=null)f.jdbc.update("DELETE FROM source_runs WHERE claim_node_id=? OR node_id=?",f.node,f.node);if(f!=null&&owner!=null){f.jdbc.update("DELETE FROM request_receipts WHERE actor_id=?",owner);f.jdbc.update("DELETE FROM users WHERE id=?",owner);}if(f!=null)f.cleanup();}
 void heartbeat(){f.tx.execute(s->f.store.save(f.node,1,f.body(at.get(),10),at.get()));}
 @Test void originalNativeOwnerCreateReceiptProvesExpectedStartWithoutInventingEmptyHeartbeat(){var value=facts.read(f.node);assertNotNull(value);assertTrue(value.enabled());assertNull(value.heartbeat());assertEquals(f.now,value.expectedSince());assertEquals(0,value.pendingServerClaims());assertFalse(value.toString().contains(f.node));}
 @Test void actualOriginalHeartbeatAndNodeLastSeenRetainRealTimeAcrossReadonlyRestartAndRotation(){heartbeat();var first=facts.read(f.node);assertNotNull(first);assertEquals(10,first.heartbeat().outboxBytes());at.set(f.now.plusSeconds(600));var later=new JdbcCollectorNodeFacts(f.db,new DataSourceTransactionManager(f.db),clock).read(f.node);assertEquals(f.now,later.heartbeat().receivedAt());assertEquals(at.get(),later.readAt());identity.actOnNode(new IdentityService.Actor(owner,"owner"),f.node,new IdentityService.NodeActionCommand(1,"rotate_token","fictional replacement",null,null),"fictional-rotate-key","fictional-csrf","https://example.invalid");var rotated=facts.read(f.node);assertNotNull(rotated);assertEquals(2,rotated.nodeRevision());assertEquals(1,rotated.heartbeat().nodeRevision());}
 @Test void damagedNativeBirthCannotMakeNoHeartbeatHealthyAndValidSnapshotDoesNotNeedExpiredResponse(){f.jdbc.update("UPDATE request_receipts SET request_hash=? WHERE actor_id=?",new byte[32],owner);assertNull(facts.read(f.node));heartbeat();assertNotNull(facts.read(f.node));f.jdbc.update("UPDATE request_receipts SET response_json=NULL WHERE actor_id=?",owner);assertNotNull(facts.read(f.node));f.jdbc.update("DELETE FROM runtime_settings WHERE setting_key=?",JdbcCollectorHeartbeats.key(f.node));assertNull(facts.read(f.node));}
 @Test void damagedHeartbeatLastSeenPermissionScopeAndCapacityAreUnknown(){heartbeat();f.jdbc.update("UPDATE collector_nodes SET last_seen_at=? WHERE id=?",java.sql.Timestamp.from(f.now.plusSeconds(1)),f.node);assertNull(facts.read(f.node));f.jdbc.update("UPDATE collector_nodes SET last_seen_at=?,permissions_json='[]' WHERE id=?",java.sql.Timestamp.from(f.now),f.node);assertNull(facts.read(f.node));f.jdbc.update("UPDATE collector_nodes SET permissions_json='[\"heartbeat:write\"]',allowed_source_ids=? WHERE id=?","[\""+"x".repeat(65536)+"\"]",f.node);assertNull(facts.read(f.node));}
 @Test void actualPendingOrUnprovenTerminalClaimsPreventReconciliationAndOverflowIsUnknown(){for(int n=0;n<201;n++)f.jdbc.update("INSERT INTO source_runs(id,claim_node_id,delivery_state,pending_count) VALUES(?,?, 'claimed',0)",UUID.randomUUID().toString(),f.node);assertNull(facts.read(f.node));f.jdbc.update("DELETE FROM source_runs WHERE claim_node_id=?",f.node);String run=UUID.randomUUID().toString();f.jdbc.update("INSERT INTO source_runs(id,claim_node_id,delivery_state,pending_count) VALUES(?,?,'complete',0)",run,f.node);var value=facts.read(f.node);assertNotNull(value);assertEquals(1,value.pendingServerClaims());f.jdbc.update("DELETE FROM source_runs WHERE id=?",run);assertEquals(0,facts.read(f.node).pendingServerClaims());}
 @Test void missingNodeConstructorSqlFaultAndOuterTransactionCannotProduceDefaultZero()throws Exception{assertNull(facts.read("fictional-missing"));assertThrows(IllegalStateException.class,()->f.tx.execute(s->facts.read(f.node)));var broken=org.mockito.Mockito.mock(DataSource.class);var tx=org.mockito.Mockito.mock(org.springframework.transaction.PlatformTransactionManager.class);var cold=new JdbcCollectorNodeFacts(broken,tx,clock);org.mockito.Mockito.verifyNoInteractions(broken,tx);org.mockito.Mockito.when(broken.getConnection()).thenThrow(new java.sql.SQLException("fictional IO unavailable"));assertNull(new JdbcCollectorNodeFacts(broken,new DataSourceTransactionManager(broken),clock).read(f.node));}
}
